import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;

public class InvoiceCalculator {
    private static final BigDecimal TAX_RATE = new BigDecimal("0.20");
    private static final String TAX_FREE_CATEGORY = "BOOKS";

    public record Line(String sku, String category, int quantity, BigDecimal unitPrice) {
        BigDecimal total() {
            return unitPrice.multiply(BigDecimal.valueOf(quantity));
        }
    }

    public BigDecimal subtotal(List<Line> lines) {
        BigDecimal subtotal = BigDecimal.ZERO;
        for (Line line : lines) {
            subtotal = subtotal.add(line.total());
        }
        return subtotal;
    }

    public BigDecimal tax(List<Line> lines) {
        BigDecimal taxable = BigDecimal.ZERO;
        for (Line line : lines) {
            if (line.category() != TAX_FREE_CATEGORY) {
                taxable = taxable.add(line.total());
            }
        }
        return taxable.multiply(TAX_RATE).setScale(2, RoundingMode.HALF_UP);
    }

    public List<Line> withoutEmpty(List<Line> lines) {
        List<Line> kept = new ArrayList<>(lines);
        for (Line line : kept) {
            if (line.quantity() == 0) {
                kept.remove(line);
            }
        }
        return kept;
    }

    public Line largest(List<Line> lines) {
        Line best = lines.get(0);
        for (Line line : lines) {
            if (line.total().compareTo(best.total()) > 0) {
                best = line;
            }
        }
        return best;
    }

    public String summary(List<Line> lines) {
        String text = "";
        for (Line line : lines) {
            text += line.quantity() + " x " + line.sku() + "\n";
        }
        return text;
    }
}

